#include <time.h>

static inline uint64_t rdtsc() {
    unsigned int lo, hi;
    __asm__ volatile ("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    // dependent add chain: 1 cycle per add
    volatile uint64_t x = 1;
    uint64_t iters = 200000000ULL;
    double t0 = now();
    uint64_t c0 = rdtsc();
    uint64_t a = 1;
    for (uint64_t i = 0; i < iters; i++) {
        a += 1; // this might be optimized... use asm
    }
    (void)a;
    // proper asm loop
    t0 = now();
    c0 = rdtsc();
    __asm__ volatile (
        "movq %1, %%rcx\n"
        "movq $1, %%rax\n"
        "1:\n"
        "addq $1, %%rax\n"
        "decq %%rcx\n"
        "jnz 1b\n"
        : "=&a"(a)
        : "r"(iters)
        : "rcx", "cc"
    );
    double t1 = now();
    uint64_t c1 = rdtsc();
    double wall = t1 - t0;
    double tsc_hz = (c1 - c0) / wall;
    double core_hz = iters / wall; // 1 add per cycle latency
    printf("wall %.4f s\n", wall);
    printf("tsc freq %.2f MHz\n", tsc_hz / 1e6);
    printf("core freq (dep add) %.2f MHz\n", core_hz / 1e6);
    printf("result %llu\n", (unsigned long long)a);
    return 0;
}
