    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32 - n)); }
static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

/* Scalar reference for correctness */
static void sha256_scalar(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a;
    uint32_t h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;
    size_t nblocks = len / 64;
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t *p = data + b*64;
        uint32_t w[64];
        for (int i = 0; i < 16; i++) {
            w[i] = ((uint32_t)p[i*4]<<24)|((uint32_t)p[i*4+1]<<16)|((uint32_t)p[i*4+2]<<8)|p[i*4+3];
        }
        for (int i = 16; i < 64; i++) {
            uint32_t s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >> 3);
            uint32_t s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >> 10);
            w[i] = w[i-16] + s0 + w[i-7] + s1;
        }
        uint32_t a=h0,b_=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
        for (int i = 0; i < 64; i++) {
            uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
            uint32_t ch = (e & f) ^ (~e & g);
            uint32_t t1 = h + S1 + ch + K[i] + w[i];
            uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
            uint32_t maj = (a & b_) ^ (a & c) ^ (b_ & c);
            uint32_t t2 = S0 + maj;
            h=g; g=f; f=e; e=d+t1; d=c; c=b_; b_=a; a=t1+t2;
        }
        h0+=a; h1+=b_; h2+=c; h3+=d; h4+=e; h5+=f; h6+=g; h7+=h;
    }
    uint32_t hs[8] = {h0,h1,h2,h3,h4,h5,h6,h7};
    for (int i = 0; i < 8; i++) {
        out[i*4] = hs[i]>>24; out[i*4+1]=hs[i]>>16; out[i*4+2]=hs[i]>>8; out[i*4+3]=hs[i];
    }
}

/* Process one 64-byte block. Uses AVX2 for message schedule (4 words at a time). */
static void sha256_block_avx2(uint32_t state[8], const uint8_t block[64]) {
    __m128i bswap_mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+0)), bswap_mask);
    __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+16)), bswap_mask);
    __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+32)), bswap_mask);
    __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+48)), bswap_mask);

    uint32_t W[64];
    _mm_storeu_si128((__m128i*)(W+0), w0);
    _mm_storeu_si128((__m128i*)(W+4), w1);
    _mm_storeu_si128((__m128i*)(W+8), w2);
    _mm_storeu_si128((__m128i*)(W+12), w3);

    /* Message schedule with SSE for s0/s1. Compute 4 words at a time.
       w[i] = w[i-16] + s0(w[i-15]) + w[i-7] + s1(w[i-2])
       For 4-wide: the dependencies within a group of 4 are only on w[i-2], which
       is within the previous group for the first 2, and within current for last 2.
       So we do 2 at a time? Let's do scalar schedule but unrolled — schedule is
       not the bottleneck vs 64 rounds of scalar adds. Skip fancy schedule. */
    for (int i = 16; i < 64; i++) {
        uint32_t x15 = W[i-15], x2 = W[i-2];
        uint32_t s0 = rotr(x15,7) ^ rotr(x15,18) ^ (x15 >> 3);
        uint32_t s1 = rotr(x2,17) ^ rotr(x2,19) ^ (x2 >> 10);
        W[i] = W[i-16] + s0 + W[i-7] + s1;
    }

    uint32_t a=state[0], b=state[1], c=state[2], d=state[3];
    uint32_t e=state[4], f=state[5], g=state[6], h=state[7];

    #pragma unroll
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + W[i];
        uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
